1	import torch
2	import triton
3	import triton.language as tl
4	from task import input_t, output_t
5	
6	# =============================================================================
7	# Blocked compact-WY Householder QR (geqrf-compatible), batched.
8	#
9	# Right-looking block algorithm (LAPACK dgeqrf structure). The per-panel
10	# factorization (unblocked geqr2 over `ib` columns + clean unit-trapezoidal V +
11	# the ib x ib block reflector T) runs in ONE custom CUDA kernel, ONE THREAD
12	# BLOCK PER MATRIX, with the L x ib panel tile resident in SHARED MEMORY (not
13	# per-thread registers). This lifts the occupancy ceiling that a register-tiled
14	# panel kernel hits (1 block/SM, 12.5% warp occupancy on the 512x32 FP32 tile).
15	# The kernel is compiled at import time with NVRTC (cuda-python bindings) and
16	# launched through the CUDA driver API with tensor.data_ptr() on torch's
17	# currently-active execution queue (the default one in normal runs; the capture
18	# queue under CUDA-graph capture) -- no torch.utils.cpp_extension (blocked here
19	# under gcc-13/nvcc-13.3), no extra execution queue, no per-call host
20	# sync/malloc, so it stays capture-safe.
21	#
22	# The trailing update C := (I - V T^T V^T) C is then 3 batched cuBLAS GEMMs
23	# (bmm V^T C, bmm T^T W, baddbmm C - V W fused), unchanged from the prior best.
24	#
25	# Output matches torch.geqrf exactly: H holds R on/above the diagonal and the
26	# reflector vectors v_i below the diagonal of column i (implicit unit diagonal);
27	# tau holds the reflector coefficients.
28	# =============================================================================
29	
30	torch.backends.cuda.matmul.allow_tf32 = False
31	torch.backends.cudnn.allow_tf32 = False
32	
33	import os
34	# Batch-adaptive warp count for the panel kernel (warps own columns round-robin).
35	# Many matrices -> small blocks (max blocks/SM); few matrices -> big blocks
36	# (max warps/matrix to hide latency). Overridable via env for tuning sweeps.
37	_NW_LARGE_B = int(os.environ.get("QR_NW_LARGE_B", "8"))    # B >= 256
38	_NW_MED_B   = int(os.environ.get("QR_NW_MED_B", "16"))     # 64 <= B < 256
39	# B < 64 (n=1024 B=60, n=4096 B=2 on the smem path): NW=16 (512-thread block).
40	# The register-cached apply needs register headroom; a 1024-thread block (NW=32)
41	# is register-starved and spills, so 16 warps now beats 32 on n=1024 (-3.2%)
42	# whereas it lost before the cache. n=4096 is unaffected (trailing-bound).
43	_NW_SMALL_B = int(os.environ.get("QR_NW_SMALL_B", "16"))   # B < 64
44	
45	
46	def _nw_for_batch(B):
47	    if B >= 256:
48	        return _NW_LARGE_B
49	    if B >= 64:
50	        return _NW_MED_B
51	    return _NW_SMALL_B
