494	def _trailing_apply(
495	    C_ptr, V_ptr, YT_ptr,
496	    B, L, ib, rest,
497	    stride_cb, stride_cr, stride_cc,
498	    stride_vb, stride_vr, stride_vc,
499	    stride_yb, stride_yr, stride_yc,
500	    IB: tl.constexpr, BM: tl.constexpr, BN: tl.constexpr,
501	):
502	    pid = tl.program_id(0)
503	    bid = tl.program_id(1)
504	    if bid >= B:
505	        return
506	    num_col_tiles = tl.cdiv(rest, BN)
507	    row_tile = pid // num_col_tiles
508	    col_tile = pid % num_col_tiles
509	    rrows = row_tile * BM + tl.arange(0, BM)
510	    ccols = col_tile * BN + tl.arange(0, BN)
511	    rmask = rrows < L
512	    cmask = ccols < rest
513	    krange = tl.arange(0, IB)
514	    kmask = krange < ib
515	
516	    cbase = C_ptr + bid * stride_cb
517	    vbase = V_ptr + bid * stride_vb
518	
519	    # V[rrows, :] : (BM, IB)
520	    vp = vbase + rrows[:, None] * stride_vr + krange[None, :] * stride_vc
521	    Vrow = tl.load(vp, mask=rmask[:, None] & kmask[None, :], other=0.0)
522	    # YT[:, ccols] : (IB, BN)
523	    yp = YT_ptr + bid * stride_yb + krange[:, None] * stride_yr + ccols[None, :] * stride_yc
524	    YT = tl.load(yp, mask=kmask[:, None] & cmask[None, :], other=0.0)
525	    delta = tl.dot(Vrow, YT, input_precision="tf32x3")                 # (BM, BN)
526	
527	    cp = cbase + rrows[:, None] * stride_cr + ccols[None, :] * stride_cc
528	    amask = rmask[:, None] & cmask[None, :]
529	    aorig = tl.load(cp, mask=amask, other=0.0)
530	    tl.store(cp, aorig - delta, mask=amask)
