533	@triton.jit
534	def _panel_kernel_triton(
535	    H_ptr, tau_ptr, V_ptr, T_ptr,
536	    B, n, k, ib,
537	    stride_hb, stride_hr, stride_hc,
538	    stride_tb, stride_tn,
539	    stride_vb, stride_vr, stride_vc,
540	    stride_Tb, stride_Tr, stride_Tc,
541	    BLOCK_L: tl.constexpr, BLOCK_IB: tl.constexpr,
542	):
543	    pid = tl.program_id(0)
544	    if pid >= B:
545	        return
546	    L = n - k
547	    row = tl.arange(0, BLOCK_L)
548	    col = tl.arange(0, BLOCK_IB)
549	    row_valid = row < L
550	    col_valid = col < ib
551	    base = H_ptr + pid * stride_hb + k * stride_hr + k * stride_hc
552	    ptrs = base + row[:, None] * stride_hr + col[None, :] * stride_hc
553	    mask = row_valid[:, None] & col_valid[None, :]
554	    panel = tl.load(ptrs, mask=mask, other=0.0)
555	    tau_vec = tl.zeros((BLOCK_IB,), dtype=tl.float32)
556	    for j in range(ib):
557	        colj = tl.sum(tl.where(col == j, panel, 0.0), axis=1)
558	        alpha = tl.sum(tl.where(row == j, colj, 0.0))
559	        below = (row > j) & row_valid
560	        tail = tl.where(below, colj, 0.0)
561	        xnorm_sq = tl.sum(tail * tail)
562	        sgn = tl.where(alpha >= 0.0, 1.0, -1.0)
563	        beta = -sgn * tl.sqrt(alpha * alpha + xnorm_sq)
564	        nonzero = xnorm_sq > 0.0
565	        tau_j = tl.where(nonzero, (beta - alpha) / tl.where(nonzero, beta, 1.0), 0.0)
566	        diagval = tl.where(nonzero, beta, alpha)
567	        denom_v = tl.where(nonzero, alpha - beta, 1.0)
568	        v = tl.where(row == j, 1.0, 0.0) + tl.where(below & nonzero, tail / denom_v, 0.0)
569	        w = tl.sum(v[:, None] * panel, axis=0)
570	        coef = tau_j * w
571	        upd_cols = col > j
572	        panel = panel - tl.where(upd_cols[None, :], v[:, None] * coef[None, :], 0.0)
573	        new_colj = tl.where(row == j, diagval, 0.0) + tl.where(below, v, 0.0)
574	        colj_final = tl.where(row < j, colj, new_colj)
575	        panel = tl.where(col[None, :] == j, colj_final[:, None], panel)
576	        tau_vec = tau_vec + tl.where(col == j, tau_j, 0.0)
577	        tl.store(tau_ptr + pid * stride_tb + (k + j) * stride_tn, tau_j)
578	    Vtile = tl.where(row[:, None] == col[None, :], 1.0, 0.0) \
579	        + tl.where((row[:, None] > col[None, :]) & mask, panel, 0.0)
580	    Vtile = tl.where(mask, Vtile, 0.0)
581	    tl.store(ptrs, panel, mask=mask)
582	    vbase = V_ptr + pid * stride_vb + row[:, None] * stride_vr + col[None, :] * stride_vc
583	    tl.store(vbase, Vtile, mask=(row_valid[:, None] & col_valid[None, :]))
584	    rowib = tl.arange(0, BLOCK_IB)
585	    tau0 = tl.sum(tl.where(col == 0, tau_vec, 0.0))
586	    T = tl.where((rowib[:, None] == 0) & (col[None, :] == 0), tau0, 0.0)
587	    for j in range(1, ib):
588	        vj = tl.sum(tl.where(col == j, Vtile, 0.0), axis=1)
589	        z = tl.sum(Vtile * vj[:, None], axis=0)
590	        z = tl.where(rowib < j, z, 0.0)
591	        tau_j = tl.sum(tl.where(col == j, tau_vec, 0.0))
592	        rhs = -tau_j * z
593	        Tcol = tl.sum(T * rhs[None, :], axis=1)
594	        Tcol = tl.where(rowib < j, Tcol, 0.0)
595	        Tcol = Tcol + tl.where(rowib == j, tau_j, 0.0)
596	        T = tl.where(col[None, :] == j, Tcol[:, None], T)
597	    tbase = T_ptr + pid * stride_Tb + rowib[:, None] * stride_Tr + col[None, :] * stride_Tc
598	    tl.store(tbase, T, mask=(rowib[:, None] < ib) & col_valid[None, :])
