601	def _qr(A, nb, use_smem):
602	    B, n, _ = A.shape
603	    H = A.clone()
604	    tau = torch.zeros((B, n), device=A.device, dtype=A.dtype)
605	    kern = _get_kernel() if use_smem else None
606	    smem_floats = kern.max_smem // 4 if use_smem else 0
607	
608	    # tf32x3 trailing tile sizes (worker-2-proven sweet spot on B200).
609	    TRAIL_BM, TRAIL_BN = 32, 64
610	    # Trailing num_warps adapts to batch: the high-batch dominant shapes
611	    # (n=512/1024, B>=60) launch thousands of (32,64) tiles, so FEWER warps per
612	    # program (2) packs more programs per SM and runs ~3% faster on n=512; the
613	    # low-batch tall shapes (n=2048 B=8, n=4096 B=2) have few programs and want
614	    # more warps (4) to fill each SM. Tunable via env for sweeps.
615	    _TRAIL_NW = int(os.environ.get("QR_TRAIL_NW", "2" if B >= 60 else "4"))
616	
617	    k = 0
618	    while k < n:
619	        L = n - k
620	        ib = min(nb, L)
621	        if use_smem:
622	            # Shrink ib so the smem panel tile fits the opt-in limit (227KB).
623	            while ib > 1 and (L * ib + L + 2 * ib + ib * ib) > smem_floats:
624	                ib -= 1
625	        BLOCK_L = _next_pow2(L)
626	        BLOCK_IB = _next_pow2(ib)
627	
628	        V = torch.empty((B, BLOCK_L, BLOCK_IB), device=A.device, dtype=A.dtype)
629	        T = torch.empty((B, BLOCK_IB, BLOCK_IB), device=A.device, dtype=A.dtype)
630	
631	        if use_smem:
632	            # NW warps, column c owned by c%NW (round-robin). The sweet spot
633	            # depends on how many matrices (blocks) there are: many matrices
634	            # already flood the 148 SMs, so a SMALL block (few warps) maximizes
635	            # blocks/SM; few matrices can't fill the SMs, so a LARGE block (many
636	            # warps) hides latency per matrix.
637	            nw = min(ib, _nw_for_batch(B))
638	            kern.launch(H, tau, V, T, B, n, k, ib, BLOCK_L, BLOCK_IB, nw * 32)
639	        else:
640	            if BLOCK_L >= 4096:
641	                num_warps = 32
642	            elif BLOCK_L >= 2048:
643	                num_warps = 16
644	            elif BLOCK_L >= 256:
645	                num_warps = 8
646	            else:
647	                num_warps = 4
648	            _panel_kernel_triton[(B,)](
649	                H, tau, V, T, B, n, k, ib,
650	                H.stride(0), H.stride(1), H.stride(2),
651	                tau.stride(0), tau.stride(1),
652	                V.stride(0), V.stride(1), V.stride(2),
653	                T.stride(0), T.stride(1), T.stride(2),
654	                BLOCK_L=BLOCK_L, BLOCK_IB=BLOCK_IB, num_warps=num_warps,
655	            )
