667	                V.stride(0), V.stride(1), V.stride(2),
668	                T.stride(0), T.stride(1), T.stride(2),
669	                YT.stride(0), YT.stride(1), YT.stride(2),
670	                IB=BLOCK_IB, BM=TRAIL_BM, BN=TRAIL_BN, num_warps=_TRAIL_NW,
671	            )
