    float* sA   = smem;               // L*ib  (column-major)
    float* sv   = sA + L * ib;        // L     current reflector v_j
    float* stau = sv + L;             // ib    tau per column
    float* sT   = stau + ib;          // ib*ib block reflector (column-major)
    float* sw   = sT + ib * ib;       // ib    scratch for T recurrence
