                if (r < j) vv = 0.0f;
                else if (r == j) vv = 1.0f;
                else vv = nonzero ? (colj[r] / denom) : 0.0f;
                sv[r] = vv;
                if (r == j) colj[r] = diagval;
                else if (r > j) colj[r] = vv;
            }
            if (tid == 0) stau[j] = tau_j;
            __syncthreads();                                // publish sv, stau[j]

            // --- apply reflector to the sub-block's own trailing cols (j,se) ---
            // Register-cache this lane's sv stripe + each column's stripe so the
            // axpy reuses both (removes the dominant MIO re-reads). The sub-block
            // is at most IS=16 wide so this is a thin BLAS-2 sweep; the wide
            // trailing columns [se,ib) are handled by the BLAS-3 apply below.
            const int NMAX = 16;
            if ((L - j) <= 32 * NMAX) {
                float svr[NMAX];
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = j + lane + (t << 5);
                    svr[t] = (r < L) ? sv[r] : 0.0f;
                }
                for (int c = j + 1 + warp; c < se; c += NW) {
                    float* colc = sA + (long)c * L;
                    float cc[NMAX];
                    float acc = 0.0f;
                    #pragma unroll
                    for (int t = 0; t < NMAX; ++t) {
                        int r = j + lane + (t << 5);
                        float v = (r < L) ? colc[r] : 0.0f;
                        cc[t] = v;
                        acc += svr[t] * v;
                    }
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_xor_sync(0xffffffff, acc, off);
                    float coef = tau_j * acc;
                    #pragma unroll
                    for (int t = 0; t < NMAX; ++t) {
                        int r = j + lane + (t << 5);
                        if (r < L) colc[r] = cc[t] - coef * svr[t];
                    }
                }
            } else {
                for (int c = j + 1 + warp; c < se; c += NW) {
                    float* colc = sA + (long)c * L;
                    float acc = 0.0f;
                    for (int r = j + lane; r < L; r += 32)
                        acc += sv[r] * colc[r];
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_xor_sync(0xffffffff, acc, off);
                    float coef = tau_j * acc;
                    for (int r = j + lane; r < L; r += 32)
                        colc[r] -= coef * sv[r];
                }
            }
            __syncthreads();                                // fence before next v
        }

        // ---- BLAS-3 apply of the finished sub-block to columns [se, ib) ----
        const int nc = ib - se;            // # trailing panel columns to update
        const int isz = se - s0;           // sub-block width actually factored
        if (nc > 0) {
            // V_s := sA[:, s0:se] is unit-lower-trapezoidal: V_s[r,p]=0 for
            // r<s0+p, =1 for r==s0+p, =sA[r, s0+p] for r>s0+p. Rows live in
            // [s0, L). We need C := (I - V_s T_s^T V_s^T) C for C = sA[:, se:ib].
            //
            // Build T_s (isz x isz, compact-WY) for the sub-block in sT's top
            // block first (dlarft forward recurrence over the IS reflectors).
            for (int idx = tid; idx < isz * isz; idx += NT) sT[idx] = 0.0f;
            __syncthreads();
            if (tid == 0) sT[0] = stau[s0];
            __syncthreads();
            for (int jj = 1; jj < isz; ++jj) {
                int col = s0 + jj;                    // panel column index
                float* colcj = sA + (long)col * L;
                float tau_jj = stau[col];
                // z[i] = V[:,s0+i] . V[:,col] for i<jj (rows >= col)
                for (int i = warp; i < jj; i += NW) {
                    float* coli = sA + (long)(s0 + i) * L;
                    float acc = 0.0f;
                    for (int r = col + lane; r < L; r += 32) {
                        float vi = coli[r];                 // r>col>s0+i
                        float vj = (r == col) ? 1.0f : colcj[r];
                        acc += vi * vj;
                    }
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_xor_sync(0xffffffff, acc, off);
                    if (lane == 0) sw[i] = acc;
                }
                __syncthreads();
                for (int i = tid; i < jj; i += NT) {
                    float t = 0.0f;
                    for (int m = 0; m < jj; ++m)
                        t += sT[(long)m * isz + i] * sw[m];
                    sT[(long)jj * isz + i] = -tau_jj * t;
                }
                __syncthreads();
                if (tid == 0) sT[(long)jj * isz + jj] = tau_jj;
                __syncthreads();
            }

            // W := V_s^T @ C   (isz x nc), column-major in sWY[p + c*isz].
            // Each warp owns one trailing column c (round-robin); cache its
            // stripe in registers once, then accumulate the dot against every
            // reflector p of the sub-block. V_s rows start at s0 (unit diag).
            const int NMAX = 16;
            for (int cc = warp; cc < nc; cc += NW) {
                int c = se + cc;
                float* colc = sA + (long)c * L;
                float creg[NMAX];
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = s0 + lane + (t << 5);
                    creg[t] = (r < L) ? colc[r] : 0.0f;
                }
                for (int p = 0; p < isz; ++p) {
                    int pc = s0 + p;                  // reflector's panel column
                    float* colp = sA + (long)pc * L;
                    float acc = 0.0f;
                    #pragma unroll
                    for (int t = 0; t < NMAX; ++t) {
                        int r = s0 + lane + (t << 5);
                        float vrp;
                        if (r < pc) vrp = 0.0f;
                        else if (r == pc) vrp = 1.0f;
                        else vrp = (r < L) ? colp[r] : 0.0f;
                        acc += vrp * creg[t];
                    }
                    #pragma unroll
                    for (int off = 16; off > 0; off >>= 1)
                        acc += __shfl_xor_sync(0xffffffff, acc, off);
                    if (lane == 0) sWY[p + cc * isz] = acc;
                }
            }
            __syncthreads();

            // YT := T_s^T @ W   (isz x nc), overwrite sWY in place via a second
            // buffer region. Compute into sT's unused area? Simpler: each thread
            // owns one (p,c) of YT, reads column c of W. Store YT into sWY2.
            float* sWY2 = sWY + isz * nc;     // isz*nc more floats
            for (int idx = tid; idx < isz * nc; idx += NT) {
                int c = idx / isz;            // 0..nc-1
                int p = idx - c * isz;        // 0..isz-1
                // YT[p,c] = sum_m T_s^T[p,m] W[m,c] = sum_m T_s[m,p] W[m,c]
                float acc = 0.0f;
                for (int m = 0; m < isz; ++m)
                    acc += sT[(long)p * isz + m] * sWY[m + c * isz];
                sWY2[idx] = acc;
            }
            __syncthreads();

            // C -= V_s @ YT.  Each warp owns one trailing column c; cache its
            // stripe, subtract V_s[:,p]*YT[p,c] accumulated over p. (V_s rows
            // start at s0; reflector p contributes only for r >= s0+p.)
            for (int cc = warp; cc < nc; cc += NW) {
                int c = se + cc;
                float* colc = sA + (long)c * L;
                float creg[NMAX];
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = s0 + lane + (t << 5);
                    creg[t] = (r < L) ? colc[r] : 0.0f;
                }
                for (int p = 0; p < isz; ++p) {
                    int pc = s0 + p;
                    float* colp = sA + (long)pc * L;
                    float y = sWY2[p + cc * isz];
                    #pragma unroll
                    for (int t = 0; t < NMAX; ++t) {
                        int r = s0 + lane + (t << 5);
                        float vrp;
                        if (r < pc) vrp = 0.0f;
                        else if (r == pc) vrp = 1.0f;
                        else vrp = (r < L) ? colp[r] : 0.0f;
                        creg[t] -= vrp * y;
                    }
                }
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = s0 + lane + (t << 5);
                    if (r < L) colc[r] = creg[t];
                }
            }
            __syncthreads();
        }
    }

