_CUDA_SRC = r'''
// Warp-per-column panel factorization. Block = ib warps (nthreads = ib*32);
// warp `c` owns column c of the panel for the whole geqr2. Per column step we
// need only 2 block barriers (publish the reflector v_j; fence before the next
// v write); every reduction is a warp-shuffle over the warp's own column, so
// the ~5-barriers/step + block-wide smem reductions of the row-major version are
// gone. The L x ib tile lives in shared memory, lifting the register-occupancy
// ceiling a register-tiled panel hits.
extern "C" __global__ void qr_panel(
        float* __restrict__ H,      // (B, n, n) row-major
        float* __restrict__ tau,    // (B, n)
        float* __restrict__ V,      // (B, BL, BIB) row-major (clean unit-trapz)
        float* __restrict__ T,      // (B, BIB, BIB) row-major
        const int B, const int n, const int k, const int ib,
        const int BL, const int BIB) {

    const int bid = blockIdx.x;
    if (bid >= B) return;

    const int L  = n - k;
    const int NT = blockDim.x;
    const int tid = threadIdx.x;
    const int lane = tid & 31;
    const int warp = tid >> 5;        // warp id
    const int NW = NT >> 5;           // number of warps; column c owned by c%NW

    extern __shared__ float smem[];
    float* sA   = smem;               // L*ib  (column-major)
    float* sv   = sA + L * ib;        // L     current reflector v_j
    float* stau = sv + L;             // ib    tau per column
    float* sT   = stau + ib;          // ib*ib block reflector (column-major)
    float* sw   = sT + ib * ib;       // ib    scratch for T recurrence

    // ---- load panel A[k:n, k:k+ib] (row-major in H) into sA (column-major) ----
    float* Abase = H + (long)bid * n * n + (long)k * n + k;
    for (int idx = tid; idx < L * ib; idx += NT) {
        int c = idx / L;
        int r = idx - c * L;
        sA[idx] = Abase[(long)r * n + c];
    }
    __syncthreads();

    // ----------------------- unblocked geqr2 over ib columns -----------------
    for (int j = 0; j < ib; ++j) {
        float* colj = sA + (long)j * L;

        // --- ALL warps cooperatively build the reflector for column j ---
        // ncu showed the panel is stall-bound at CTA barriers (35% of stall
        // cycles): the old single-warp build left NW-1 warps idle waiting at the
        // barrier behind a serial O(L/32) reduction+write. Spread both the
        // xnorm reduction and the v-write across ALL NT threads so the serial
        // pre-barrier section shrinks ~NWx; every thread then recomputes the
        // (uniform) reflector scalars from the block-reduced xnorm so no
        // broadcast is needed. Cost: one extra barrier inside the build, paid
        // back by the much shorter critical section.
        float alpha = colj[j];   // read BEFORE any thread overwrites colj below
        {
            // each thread reduces its stripe of colj[r]^2 for r>j
            float partial = 0.0f;
            for (int r = j + 1 + tid; r < L; r += NT) {
                float x = colj[r];
                partial += x * x;
            }
            #pragma unroll
            for (int off = 16; off > 0; off >>= 1)
                partial += __shfl_xor_sync(0xffffffff, partial, off);
            if (lane == 0) sw[warp] = partial;              // warp partial
        }
        __syncthreads();                                    // sw[*] ready
        float xnorm_sq = 0.0f;
        for (int w = 0; w < NW; ++w) xnorm_sq += sw[w];      // block sum (uniform)
        float sgn = (alpha >= 0.0f) ? 1.0f : -1.0f;
        float beta = -sgn * sqrtf(alpha * alpha + xnorm_sq);
        bool nonzero = xnorm_sq > 0.0f;
        float beta_safe = nonzero ? beta : 1.0f;
        float tau_j = nonzero ? (beta - alpha) / beta_safe : 0.0f;
        float diagval = nonzero ? beta : alpha;
        float denom = nonzero ? (alpha - beta) : 1.0f;
        // all threads write their stripe of sv and finalize column j
        for (int r = tid; r < L; r += NT) {
            float vv;
            if (r < j) vv = 0.0f;
            else if (r == j) vv = 1.0f;
            else vv = nonzero ? (colj[r] / denom) : 0.0f;
            sv[r] = vv;
            if (r == j) colj[r] = diagval;
            else if (r > j) colj[r] = vv;
        }
        if (tid == 0) stau[j] = tau_j;
        __syncthreads();                                    // publish sv, stau[j]

        // --- each warp applies the reflector to its round-robin columns c>j ---
        // (tau_j already computed above, identical in every thread)
        // The panel is MIO-bound (smem throughput). When the live column fits in
        // <=NMAX per-lane chunks (the dominant n<=512 panels), cache this lane's
        // sv stripe in registers ONCE (reused for every column the warp owns)
        // and cache each column's stripe across the dot so the axpy reuses it.
        // That removes the axpy's re-read of both sv and colc from smem (the two
        // dominant MIO loads). Larger panels fall back to the plain 2-read loop
        // (a 128-chunk register cache would spill to local memory).
        const int NMAX = 16;
        if ((L - j) <= 32 * NMAX) {
            float svr[NMAX];
            #pragma unroll
            for (int t = 0; t < NMAX; ++t) {
                int r = j + lane + (t << 5);
                svr[t] = (r < L) ? sv[r] : 0.0f;
            }
            for (int c = warp; c < ib; c += NW) {
                if (c <= j) continue;
                float* colc = sA + (long)c * L;
                float cc[NMAX];
                float acc = 0.0f;
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = j + lane + (t << 5);
                    float v = (r < L) ? colc[r] : 0.0f;
                    cc[t] = v;
                    acc += svr[t] * v;
                }
                #pragma unroll
                for (int off = 16; off > 0; off >>= 1)
                    acc += __shfl_xor_sync(0xffffffff, acc, off);
                float coef = tau_j * acc;
                #pragma unroll
                for (int t = 0; t < NMAX; ++t) {
                    int r = j + lane + (t << 5);
                    if (r < L) colc[r] = cc[t] - coef * svr[t];
                }
            }
        } else {
            for (int c = warp; c < ib; c += NW) {
                if (c <= j) continue;
                float* colc = sA + (long)c * L;
                float acc = 0.0f;
                for (int r = j + lane; r < L; r += 32)
                    acc += sv[r] * colc[r];
                #pragma unroll
                for (int off = 16; off > 0; off >>= 1)
                    acc += __shfl_xor_sync(0xffffffff, acc, off);
                float coef = tau_j * acc;
                for (int r = j + lane; r < L; r += 32)
                    colc[r] -= coef * sv[r];
            }
        }
        __syncthreads();                                    // fence before next v write
    }

