const int nc = ib - se;            // # trailing panel columns to update
const int isz = se - s0;           // sub-block width actually factored
if (nc > 0) {
    // V_s := sA[:, s0:se] is unit-lower-trapezoidal: V_s[r,p]=0 for
    // r<s0+p, =1 for r==s0+p, =sA[r, s0+p] for r>s0+p. Rows live in
    // [s0, L). We need C := (I - V_s T_s^T V_s^T) C for C = sA[:, se:ib].
    //
    // Build T_s (isz x isz, compact-WY) for the sub-block in sT's top
    // block first (dlarft forward recurrence over the IS reflectors).
    for (int idx = tid; idx < isz * isz; idx += NT) sT[idx] = 0.0f;
    __syncthreads();
    if (tid == 0) sT[0] = stau[s0];
    __syncthreads();
    for (int jj = 1; jj < isz; ++jj) {
        int col = s0 + jj;                    // panel column index
        float* colcj = sA + (long)col * L;
        float tau_jj = stau[col];
        // z[i] = V[:,s0+i] . V[:,col] for i<jj (rows >= col)
        for (int i = warp; i < jj; i += NW) {
            float* coli = sA + (long)(s0 + i) * L;
            float acc = 0.0f;
            for (int r = col + lane; r < L; r += 32) {
                float vi = coli[r];                 // r>col>s0+i
                float vj = (r == col) ? 1.0f : colcj[r];
                acc += vi * vj;
